-- Create table
-- Sa PostgreSQL, gumamit ng double quote para ma-preserve
-- ang capitalization ng table at column names.
-- Kapag walang double quote, automatic itong nagiging lowercase.
CREATE TABLE IF NOT EXISTS "tblTransactionItems" (

    --"TransactionItemsID" UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    "TransacItemsID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TransactionID" INT,
    "ProductID" INT,
    "ProductName" TEXT,
    "Category" TEXT,
    "Price" DECIMAL(10,2),
    "Cost" DECIMAL(10,2),
    "DiscountType" TEXT,
    "Quantity" DECIMAL(10,0),
    "DateAdded" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "CreatedBy" UUID
        REFERENCES auth.users(id)
        ON DELETE CASCADE
);


-- CREATE INDEX

CREATE INDEX IF NOT EXISTS "idx_tblTransactionItems_TransacItemsID"
ON "tblTransactionItems" ("TransacItemsID");
CREATE INDEX IF NOT EXISTS "idx_tblTransactionItems_TransacItemsID"
ON "tblTransactionItems" ("TransacItemsID");
 

-- Enable Row Level Security (RLS)

-- Makaka-edit/delete lang ng item
-- kung kanino naka-assign

ALTER TABLE "tblTransactionItems"
ENABLE ROW LEVEL SECURITY;


-- Policy: Users can view all TransactionItems

CREATE POLICY "User can view all TransactionItems"

ON "tblTransactionItems"

FOR SELECT

USING (true);


-- Policy: Users can create TransactionItems

CREATE POLICY "User can create TransactionItems"

ON "tblTransactionItems"

FOR INSERT

WITH CHECK (auth.uid() = "CreatedBy");


-- Policy: User can update TransactionItems
-- that they created or assigned

CREATE POLICY "User can update TransactionItems that they created or assigned"

ON "tblTransactionItems"

FOR UPDATE

USING (
    auth.uid() = "CreatedBy"
)

WITH CHECK (
    auth.uid() = "CreatedBy"
);


-- Policy: Only creators can delete TransactionItems

CREATE POLICY "Only creators can delete TransactionItems"

ON "tblTransactionItems"

FOR DELETE

USING (auth.uid() = "CreatedBy");


